/* build121: the build 32-41 imperative/prohibitive/subjunctive block that lived here was removed. It replaced the
   core parse() in the page only, so the app parsed differently from the measured engine (kontu-eymu for kon-tu-eymu);
   the engine has carried its own imperative, prohibitive and subjunctive handling since then. */



/* =====================================================================
   Build 42 — three post-parse repairs, applied once to the final parse.
   Kept out of parse() itself so the recursive root search is untouched,
   the same way reflexiveSplit/splitPort/indLabel are staged.
   ===================================================================== */

/* 42a: orthographic display fidelity.
   orth() normalises v/b->f, c/qu->k, z->s, ll->y, ce/ci->se/si and strips
   accents so a root can be FOUND. Until now the normalised string was also
   what got DISPLAYED, so pobrengen came back as pofre-nge-n and the user was
   shown a spelling they did not type. orthTrace() records, for every
   character of the normalised string, which character of the original it
   came from; surfaceMap() then re-cuts the ORIGINAL word at the morpheme
   boundaries the parser found. Lookup still uses the normalised form. */
function orthTrace(s){
  s = String(s).toLowerCase();
  var out = '', map = [], i = 0, ACC = 'áéíóú', PLAIN = 'aeiou';
  while(i < s.length){
    var two = s.substr(i,2);
    if(two === 'ch'){ out += 'ch'; map.push(i, i); i += 2; continue; }
    if(two === 'ce'){ out += 'se'; map.push(i, i+1); i += 2; continue; }
    if(two === 'ci'){ out += 'si'; map.push(i, i+1); i += 2; continue; }
    if(two === 'qu'){ out += 'k';  map.push(i);      i += 2; continue; }
    if(two === 'll'){ out += 'y';  map.push(i);      i += 2; continue; }
    var c = s[i], r = c, ai = ACC.indexOf(c);
    if(c === 'v' || c === 'b') r = 'f';
    else if(c === 'c') r = 'k';
    else if(c === 'z') r = 's';
    else if(ai >= 0) r = PLAIN[ai];
    out += r; map.push(i); i++;
  }
  map.push(s.length);                 /* sentinel: end of string */
  return { norm: out, map: map };
}

/* the parser writes phonetic fusion as X(e); strip that for offset maths */
function _bare(f){ return String(f == null ? '' : f).replace(/\([^)]*\)/g, ''); }

