var _GX=null; function GX(){ if(!_GX){ _GX=Object.assign({},GLOSS); if(typeof GLOSS_VIEW!=='undefined') for(const k in GLOSS_VIEW){
      /* an analyst ruling (R) or AVENUE-translation gloss (C) on the root is kept over a dictionary text for its citation form */
      const rt=k.replace(/(ün|n)$/,''); if(GLOSS[rt] && /^[RC]$/.test(GLOSS[rt].src) && k!==rt) continue;
      if(GLOSS[k] && /^[RC]$/.test(GLOSS[k].src)) continue;   /* build136: a ruling on the same key also wins (nentu) */
      _GX[k]=GLOSS_VIEW[k]; } } return _GX; }

/* ---- build129: sentence mode. Each word goes through the same steps as the single-word analyser (grafemario detected on
   the whole sentence, parse43, category re-parse), then contextResolve() (engine build 123) uses the neighbouring words. ---- */
function analyseSentence(text){
  const toks=(text.match(/[A-Za-zÑñÜüÁÉÍÓÚáéíóúḻṉṯ'’·̱]+/g)||[]);
  const sel=(document.getElementById('abc')||{}).value||'auto';
  const OD=(typeof ORTHO!=='undefined')?(sel==='auto'?ORTHO.detect(text,orthoScorer):{sys:sel}):{sys:'unificado'};
  const uni=toks.map(t=>(typeof ORTHO!=='undefined' && OD.sys!=='unificado')?ORTHO.toUnificado(t,OD.sys).text:t.toLowerCase());
  const ps=uni.map(w=>{ let r=null; try{ r=parse43(w,'',3,false); if(r && !r.nvRule){ const inf=inferCat(r.root); if(inf){ const r2=parse43(w,inf,3,false); if(r2 && !r2.nvRule) r=r2; } } }catch(e){} return r; });
  const res=(typeof contextResolve==='function')?contextResolve(uni,ps):ps;
  return {toks,uni,res,sys:OD.sys};
}
function renderSentence(){
  const box=document.getElementById('sentout'); const text=document.getElementById('sent').value.trim();
  if(!text){ box.innerHTML=''; return; }
  const ES=(typeof LANG!=='undefined' && LANG==='es'); const A=analyseSentence(text);
  const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;');
  const outSel=(document.getElementById('abcout')||{}).value||'same'; const tgt=outSel==='same'?A.sys:outSel;
  const D=s=>{ if(s==null||tgt==='unificado'||typeof ORTHO==='undefined') return s; let x=String(s); if(tgt==='ragileo') x=x.replace(/v/g,'f'); return ORTHO.fromUnificado(x,tgt); };
  const WC=x=>ES?((typeof WCLS_ES!=='undefined'&&WCLS_ES[x])||x):x;
  let h='<table class=sent style="border-collapse:collapse;font-size:14px;width:100%"><thead><tr>'+['#',ES?'palabra':'word',ES?'segmentación':'segmentation',ES?'posiciones':'slots',ES?'clase':'class',ES?'nota':'note'].map(x=>'<th style="text-align:left;border-bottom:1px solid var(--line);padding:4px 6px;color:var(--mut);font-weight:500">'+x+'</th>').join('')+'</tr></thead><tbody>';
  A.res.forEach((r,i)=>{
    let seg='', sl='', cl='', note='';
    if(r){ seg=r.words?r.words.map(D).join(' '):D([r.root].concat((r.m||[]).map(x=>x.f)).join('-'));
      sl=(r.m||[]).filter(x=>x.slot!=null).map(x=>x.slot+' '+x.gloss).join(' · ');
      cl=WC(r.wclass||''); 
      if(r.ctx) note=(ES?'contexto: ':'context: ')+r.ctx;
      else if(r.nvFlag) note=(ES?'quizás no es verbo (p = ':'possibly not a verb (p = ')+r.nvFlag.p+')';
      else if(r.alts && r.alts.length) note=(ES?'otra lectura: ':'other reading: ')+r.alts[0].reading;
      if(r.wclass==='verb' && typeof MEANING!=='undefined'){ try{ const M=MEANING.compose(r,GX()); if(M && M.ok) note=(note?note+' · ':'')+'«'+M.sentence+'»'; }catch(e){} } }
    h+='<tr><td style="padding:4px 6px;color:var(--mut)">'+(i+1)+'</td><td style="padding:4px 6px"><a href="#" data-w="'+esc(A.toks[i])+'" class=sentw>'+esc(A.toks[i])+'</a></td><td style="padding:4px 6px;font-family:ui-monospace,Menlo,monospace">'+esc(seg)+'</td><td style="padding:4px 6px;font-size:12.5px">'+esc(sl)+'</td><td style="padding:4px 6px">'+esc(cl)+'</td><td style="padding:4px 6px;font-size:12.5px;color:var(--mut)">'+esc(note)+'</td></tr>';
  });
  h+='</tbody></table>';
  if(A.sys && A.sys!=='unificado') h='<div class=alt><b>Grafemario:</b> '+ORTHO.NAME[A.sys]+'</div>'+h;
  box.innerHTML=h;
  box.querySelectorAll('a.sentw').forEach(a=>a.addEventListener('click',ev=>{ ev.preventDefault(); const i=document.getElementById('w'); i.value=a.dataset.w; render(); i.scrollIntoView({behavior:'smooth',block:'center'}); }));
}
document.getElementById('sentgo').addEventListener('click',renderSentence);
document.getElementById('sent').addEventListener('keydown',e=>{ if(e.key==='Enter' && !e.shiftKey){ e.preventDefault(); renderSentence(); } });

